<?php
require_once __DIR__.'/core/auth.php';require_once __DIR__.'/core/security.php';require_once __DIR__.'/core/settings.php';require_once __DIR__.'/core/autocontrollo_haccp.php';require_login();$user=current_user();if(!$user||!user_has_department($user,'Amministrazione')){http_response_code(403);exit('Accesso negato.');}$env=require __DIR__.'/config/env.php';$base=rtrim($env['app']['base_url']??'','/');$pdo=db();ensure_autocontrollo_haccp_inspections_tables($pdo);$range=get_summer_season_range($pdo);$today=new DateTimeImmutable('today',new DateTimeZone('Europe/Rome'));$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check((string)($_POST['csrf']??''))){http_response_code(400);exit('Token CSRF non valido.');}try{$action=(string)($_POST['action']??'');if($action==='start'){$id=autocontrollo_haccp_start($pdo,$range,(string)($_POST['scheduled_date']??''),(int)$user['id']);header('Location: '.$base.'/autocontrollo_haccp.php?inspection='.$id);exit;}if($action==='check'){$inspectionId=(int)($_POST['inspection_id']??0);$resultId=(int)($_POST['result_id']??0);$clean=(string)($_POST['is_clean']??'');if(!in_array($clean,['0','1'],true))throw new InvalidArgumentException('Indicare se la superficie è stata pulita correttamente.');$stmt=$pdo->prepare("UPDATE autocontrollo_haccp_inspection_results r JOIN autocontrollo_haccp_inspections i ON i.id=r.inspection_id SET r.is_clean=?,r.checked_at=NOW() WHERE r.id=? AND r.inspection_id=? AND r.checked_at IS NULL AND i.status='in_corso'");$stmt->execute([(int)$clean,$resultId,$inspectionId]);if($stmt->rowCount()!==1)throw new RuntimeException('Passaggio non valido o già registrato.');$stmt=$pdo->prepare('SELECT COUNT(*) FROM autocontrollo_haccp_inspection_results WHERE inspection_id=? AND checked_at IS NULL');$stmt->execute([$inspectionId]);if((int)$stmt->fetchColumn()===0){$pdo->prepare("UPDATE autocontrollo_haccp_inspections SET status='completata',completed_at=NOW() WHERE id=? AND status='in_corso'")->execute([$inspectionId]);autocontrollo_haccp_send_report($pdo,$inspectionId);header('Location: '.$base.'/autocontrollo_haccp.php?completed='.$inspectionId);exit;}header('Location: '.$base.'/autocontrollo_haccp.php?inspection='.$inspectionId);exit;}throw new InvalidArgumentException('Azione non valida.');}catch(Throwable $e){$error=$e->getMessage();}}
$inspectionId=(int)($_GET['inspection']??($_POST['inspection_id']??0));if($inspectionId<=0){$stmt=$pdo->prepare("SELECT id FROM autocontrollo_haccp_inspections WHERE season_start=? AND season_end=? AND status='in_corso' ORDER BY scheduled_date LIMIT 1");$stmt->execute([$range['start']??'',$range['end']??'']);$inspectionId=(int)($stmt->fetchColumn()?:0);}$active=null;$current=null;$results=[];$progress=[0,0];if($inspectionId){$stmt=$pdo->prepare('SELECT * FROM autocontrollo_haccp_inspections WHERE id=?');$stmt->execute([$inspectionId]);$active=$stmt->fetch(PDO::FETCH_ASSOC);if($active&&$active['status']==='in_corso'){$stmt=$pdo->prepare('SELECT * FROM autocontrollo_haccp_inspection_results WHERE inspection_id=? ORDER BY sort_order');$stmt->execute([$inspectionId]);$results=$stmt->fetchAll(PDO::FETCH_ASSOC);foreach($results as$row)if($current===null&&$row['checked_at']===null)$current=$row;$progress=[count($results),count(array_filter($results,static fn($row)=>$row['checked_at']!==null))];}}
$stmt=$pdo->prepare("SELECT i.*,u.email operator_email,TRIM(CONCAT_WS(' ',NULLIF(u.nome,''),NULLIF(u.cognome,''))) operator_name,COUNT(r.id) surface_count,COALESCE(SUM(r.is_clean=0),0) anomaly_count FROM autocontrollo_haccp_inspections i LEFT JOIN users u ON u.id=i.operator_id LEFT JOIN autocontrollo_haccp_inspection_results r ON r.inspection_id=i.id WHERE i.season_start=? AND i.season_end=? GROUP BY i.id ORDER BY i.scheduled_date DESC");$stmt->execute([$range['start']??'',$range['end']??'']);$inspections=$stmt->fetchAll(PDO::FETCH_ASSOC);$completed=[];foreach($inspections as$item)if($item['status']==='completata')$completed[]=$item['scheduled_date'];$nextDate=autocontrollo_haccp_next_date(autocontrollo_haccp_schedule($range),$completed);$viewId=(int)($_GET['view']??0);$viewResults=[];if($viewId){$stmt=$pdo->prepare('SELECT * FROM autocontrollo_haccp_inspection_results WHERE inspection_id=? ORDER BY sort_order');$stmt->execute([$viewId]);$viewResults=$stmt->fetchAll(PDO::FETCH_ASSOC);}$title='Autocontrollo Pulizia HACCP';include __DIR__.'/partials/header.php';?>
<div class="mb-4"><div class="text-muted small text-uppercase fw-semibold">Autocontrollo</div><h1 class="h4"><i class="bi bi-shield-check me-1"></i>Pulizia HACCP</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;if(isset($_GET['completed'])):?><div class="alert alert-success">Procedura completata e rapporto inviato agli utenti Amministrazione.</div><?php endif;?><div class="alert alert-info"><strong>Sanificazione HACCP:</strong> il responsabile deve verificare e confermare la corretta pulizia di tutte le superfici previste. La superficie interna del frigo viene controllata settimanalmente.</div>
<?php if($active&&$current):$percent=(int)round($progress[1]/max(1,$progress[0])*100);?><div class="card shadow-sm border-primary mx-auto" style="max-width:720px"><div class="card-body p-3 p-md-4"><div class="d-flex justify-content-between"><span class="badge text-bg-primary">Superficie <?=$progress[1]+1?> di <?=$progress[0]?></span><span><?=$percent?>%</span></div><div class="progress my-2 mb-4"><div class="progress-bar" style="width:<?=$percent?>%"></div></div><div class="text-muted text-uppercase small"><?=e(ucfirst($current['frequency']))?></div><h2 class="h3 mb-4"><?=e($current['surface_label'])?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="check"><input type="hidden" name="inspection_id" value="<?=(int)$active['id']?>"><input type="hidden" name="result_id" value="<?=(int)$current['id']?>"><fieldset><legend class="h5">La superficie è stata pulita correttamente?</legend><div class="row g-2 mb-3"><div class="col-6"><input class="btn-check" type="radio" name="is_clean" id="haccpYes" value="1" required><label class="btn btn-outline-success btn-lg w-100" for="haccpYes">Sì</label></div><div class="col-6"><input class="btn-check" type="radio" name="is_clean" id="haccpNo" value="0" required><label class="btn btn-outline-danger btn-lg w-100" for="haccpNo">No</label></div></div></fieldset><button class="btn btn-primary btn-lg w-100">Salva e continua</button></form></div></div>
<?php else:?><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5">Prossimo controllo giornaliero</h2><?php if(empty($range['start'])||empty($range['end'])):?><div class="alert alert-warning mb-0">Configurare le date di apertura e chiusura della stagione.</div><?php elseif(!$nextDate):?><div class="alert alert-success mb-0">Tutte le procedure stagionali sono completate.</div><?php else:$available=$nextDate<=$today->format('Y-m-d');?><div class="fs-4 fw-semibold mb-1"><?=e((new DateTimeImmutable($nextDate))->format('d/m/Y'))?></div><?php if(in_array('fridge_inside',array_column(autocontrollo_haccp_surfaces_for_date($range,$nextDate),'code'),true)):?><div class="small text-muted mb-3"><i class="bi bi-calendar-week me-1"></i>Include la pulizia settimanale della superficie interna del frigo.</div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="start"><input type="hidden" name="scheduled_date" value="<?=e($nextDate)?>"><button class="btn btn-primary" <?=$available?'':'disabled'?>><?=$available?'Avvia procedura':'Non ancora disponibile'?></button></form><?php endif;?></div></div><?php endif;?>
<div class="card shadow-sm mt-4"><div class="card-header bg-white"><h2 class="h5 mb-0">Rilevazioni effettuate</h2></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data e ora</th><th>Giorno</th><th>Operatore</th><th>Superfici</th><th>Anomalie</th><th>Stato</th><th></th></tr></thead><tbody><?php if(!$inspections):?><tr><td colspan="7" class="text-center text-muted py-4">Nessuna procedura avviata.</td></tr><?php endif;foreach($inspections as$item):?><tr><td><?=e((new DateTimeImmutable($item['started_at']))->format('d/m/Y H:i'))?></td><td><?=e((new DateTimeImmutable($item['scheduled_date']))->format('d/m/Y'))?></td><td><?=e($item['operator_name']?:($item['operator_email']??'—'))?></td><td><?=(int)$item['surface_count']?></td><td><?php if((int)$item['anomaly_count']):?><span class="badge text-bg-danger"><?=(int)$item['anomaly_count']?> anomalie</span><?php else:?><span class="badge text-bg-success">Nessuna</span><?php endif;?></td><td><?=e($item['status'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="?view=<?=(int)$item['id']?>#dettaglio">Dettagli</a><?php if($item['status']==='in_corso'):?> <a class="btn btn-sm btn-primary" href="?inspection=<?=(int)$item['id']?>">Continua</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if($viewResults):?><div class="card shadow-sm mt-3" id="dettaglio"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Superficie</th><th>Frequenza</th><th>Pulizia corretta</th><th>Verificata</th></tr></thead><tbody><?php foreach($viewResults as$row):?><tr class="<?=$row['is_clean']!==null&&!(int)$row['is_clean']?'table-danger':''?>"><td><?=e($row['surface_label'])?></td><td><?=e(ucfirst($row['frequency']))?></td><td><?=$row['is_clean']===null?'—':((int)$row['is_clean']?'Sì':'<strong>NO — Anomalia</strong>')?></td><td><?=$row['checked_at']?e((new DateTimeImmutable($row['checked_at']))->format('d/m/Y H:i')):'—'?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;include __DIR__.'/partials/footer.php';?>
